SELECT id, title, difficulty, knowledge_point, input_example, output_example, created_at
FROM c_questions


        AND difficulty = #{difficulty}


        AND knowledge_point = #{knowledgePoint}


        AND (title LIKE CONCAT('%', #{keyword}, '%') OR problem LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY created_at DESC

SELECT * FROM c_questions


        AND difficulty = #{difficulty}


ORDER BY RAND() LIMIT #{limit}
